+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private final ContactMessageStore messageStore;
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<ContactMessage> messagesGrid = new Grid<>(ContactMessage.class, false);
+
+    private boolean resettingFields;
+    private boolean validationAttempted;
+
+    public ContactView(ContactMessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        setPadding(true);
+        setSpacing(true);
+
+        FormLayout form = new FormLayout();
+        form.setAutoResponsive(true);
+        form.setExpandColumns(true);
+        form.setExpandFields(true);
+        form.setMaxWidth("42rem");
+
+        nameField.setWidthFull();
+        emailField.setWidthFull();
+        phoneField.setWidthFull();
+        messageField.setWidthFull();
+        messageField.setMinRows(4);
+        emailField.setManualValidation(true);
+
+        form.addFormRow(nameField, emailField);
+        form.addFormRow(phoneField);
+        form.addFormRow(messageField);
+        form.add(sendButton);
+
+        sendButton.addClickListener(event -> sendMessage());
+        sendButton.addClickShortcut(Key.ENTER);
+        sendButton.setEnabled(true);
+
+        nameField.addValueChangeListener(event -> fieldEdited());
+        emailField.addValueChangeListener(event -> fieldEdited());
+        phoneField.addValueChangeListener(event -> fieldEdited());
+        messageField.addValueChangeListener(event -> fieldEdited());
+
+        messagesGrid.addColumn(ContactMessage::name).setHeader("Name").setKey("name");
+        messagesGrid.addColumn(ContactMessage::message).setHeader("Message").setKey("message");
+        messagesGrid.setWidthFull();
+        refreshMessages();
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, messagesGrid);
+    }
+
+    private void fieldEdited() {
+        if (resettingFields) {
+            return;
+        }
+        sendButton.setEnabled(true);
+        if (validationAttempted) {
+            validateForm();
+        }
+    }
+
+    private void sendMessage() {
+        validationAttempted = true;
+        if (!validateForm()) {
+            return;
+        }
+
+        ContactMessage sent = new ContactMessage(
+                nameField.getValue().trim(),
+                emailField.getValue().trim(),
+                phoneField.getValue().trim(),
+                messageField.getValue());
+        messageStore.add(sent);
+        refreshMessages();
+
+        resettingFields = true;
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+        resettingFields = false;
+        clearValidation();
+        validationAttempted = false;
+
+        sendButton.setEnabled(false);
+        Notification notification = new Notification("Message sent", 3000);
+        add(notification);
+        notification.open();
+    }
+
+    private boolean validateForm() {
+        clearValidation();
+
+        boolean valid = true;
+        if (nameField.getValue().isBlank()) {
+            nameField.setErrorMessage("Name is required");
+            nameField.setInvalid(true);
+            valid = false;
+        }
+
+        String email = emailField.getValue().trim();
+        String phone = phoneField.getValue();
+        boolean invalidEmail = !email.isEmpty()
+                && emailField.getDefaultValidator().apply(email, new ValueContext(emailField)).isError();
+        if (invalidEmail) {
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            emailField.setInvalid(true);
+            valid = false;
+        } else if (email.isEmpty() && phone.isBlank()) {
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            emailField.setInvalid(true);
+            valid = false;
+        }
+
+        String message = messageField.getValue();
+        if (message.isBlank()) {
+            messageField.setErrorMessage("Message is required");
+            messageField.setInvalid(true);
+            valid = false;
+        } else if (message.codePointCount(0, message.length()) > MAX_MESSAGE_LENGTH) {
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            messageField.setInvalid(true);
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private void clearValidation() {
+        nameField.setInvalid(false);
+        nameField.setErrorMessage(null);
+        emailField.setInvalid(false);
+        emailField.setErrorMessage(null);
+        messageField.setInvalid(false);
+        messageField.setErrorMessage(null);
+    }
+
+    private void refreshMessages() {
+        messagesGrid.setItems(messageStore.getNewestFirst());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !nameField.getValue().isEmpty()
+                || !emailField.getValue().isEmpty()
+                || !phoneField.getValue().isEmpty()
+                || !messageField.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        ContinueNavigationAction navigation = event.postpone();
+        Dialog confirmation = new Dialog();
+        confirmation.add(new Paragraph("You have an unfinished message. Discard it?"));
+        confirmation.setCloseOnEsc(false);
+        confirmation.setCloseOnOutsideClick(false);
+
+        Button keepEditing = new Button("Keep editing", click -> {
+            confirmation.close();
+            navigation.cancel();
+        });
+        Button discard = new Button("Discard", click -> {
+            confirmation.close();
+            navigation.proceed();
+        });
+        confirmation.add(new HorizontalLayout(keepEditing, discard));
+        confirmation.open();
+    }
+}
